using UnityEngine;

namespace NatureCalls.Facility
{
    /// <summary>
    /// Formal mess art (GLOSSARY Mess/StoolKind): meshes from scripts/blender/mess_models.py and URP materials.
    /// Generated by Editor/MessArtSetup into Assets/Art/Mess/Resources/MessArt.asset; missing art falls back to primitives.
    /// </summary>
    [CreateAssetMenu(menuName = "NatureCalls/Mess Art")]
    public sealed class MessArt : ScriptableObject
    {
        public Mesh SoftSwirl, SoftSquashed, HardLog, HardPellets, LooseSplat, Vomit, UrinePuddle, ToiletSmear;
        public Material Stool, StoolDry, Loose, Bubble, VomitBase, VomitChunk, Urine, Smear, Backflow, BackflowBubble;
        /// <summary>Particle materials (URP Particles/Unlit) using the stink and comfort sprites.</summary>
        public Material Stink, Sparkle, Splash;

        private static MessArt current;
        private static bool loaded;
        public static MessArt Current
        {
            get
            {
                if (!loaded) { current = Resources.Load<MessArt>("MessArt"); loaded = true; }
                return current;
            }
        }
    }
}
